INSERT INTO hotel (hotel_id, username, password, name, union_id, address, phone_no, email, photo, description, created_on) VALUES
  (1, 'seapearl', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Sea Pearl Beach Resort & Spa', 848, 'Jaliapalong, Inani, Ukhia, Cox''s Bazar 4750 Bangladesh', '01715097720', 'seapearl@gmail.com', '/images/hotels/sea-pearl.jpg', 'Spacious studio rooms with modern amenities and beautiful views. Tasty food at on-site restaurant, friendly staff, and daily housekeeping. Exciting water park for family fun, private beach, and stunning sea views.', '2024-02-09 10:00:00'),
  (2, 'oceanparadise', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Ocean Paradise Hotel & Resort', 821, '28-29 Hotel Motel Zone, Kolatoli Road, Cox''s Bazar 4700 Bangladesh', '01715097720', 'oceanparadise@gmail.com', '/images/hotels/ocean-paradise.jpg', 'Pleasant stay, helpful staff, and good amenities. Prime beach location with 5-star ambiance. Impressive exterior, spacious rooms, and commendable food. Rooftop BBQ and amazing ocean views.', '2024-02-09 10:00:00'),
  (3, 'grandsylhet', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Grand Sylhet Hotel & Resort', 2515, 'Airport Road, Boroshala Khadimnagar, Sylhet City 3100 Bangladesh', '01715097720', 'grandsylhet@gmail.com', '/images/hotels/lobby.jpg', 'Conveniently located within easy access of the airport, city center and other business districts, Grand Sylhet Hotel & Resort has 235 spacious rooms and suites. Each room offers luxury space and chic design elements.', '2024-02-09 10:00:00'),
  (4, 'Roseview', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Rose View Hotel', 2513, 'Shahjalal Uposhohor, Sylhet City 3100 Bangladesh', '01715097720', 'Roseview@gmail.com', '/images/rooms/suite.jpg', 'Rose View Hotel welcomes you to enjoy comfort and luxury with five star facilities and world class hospitality. 140 deluxe and suite rooms, a fitness centre, Thai spa and a heated rooftop swimming pool, centrally located near Osmani International Airport.', '2024-02-09 10:00:00'),
  (5, 'aronnok', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Aronnok Holiday Resort', 341, 'Rangamati Cantonment, Rangamati Bangladesh', '01715097720', 'aronnok@gmail.com', '/images/hotels/kaptai-resort.jpg', 'Aronnok Holiday Resort is a secured place located in Rangamati Cantonment. The serene beauty of Kaptai lake is all around the resort. Rooms are luxurious with air conditioning and the food is among the best in Rangamati.', '2024-02-09 10:00:00'),
  (6, 'longbeach', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Long Beach Hotel', 821, '14 Kolatoli Road, Cox''s Bazar 4700 Bangladesh', '01811223344', 'reservation.longbeach@example.com', '/images/hotels/long-beach.jpg', 'A tall, bright hotel a few steps from Kolatoli beach with sea-facing balconies, a rooftop pool and a 24-hour seafood restaurant.', '2024-02-09 10:00:00'),
  (7, 'panpacific', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Pan Pacific Sonargaon Dhaka', 3271, '107 Kazi Nazrul Islam Avenue, Karwan Bazar, Dhaka 1215', '01711556677', 'stay.sonargaon@example.com', '/images/hotels/pan-pacific.jpg', 'A landmark of Dhaka hospitality since 1981, with a lush garden courtyard, an outdoor pool and some of the best buffets in the city.', '2024-02-09 10:00:00'),
  (8, 'intercontinental', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'InterContinental Dhaka', 3271, '1 Minto Road, Shahbag, Dhaka 1000', '01711998877', 'dhaka.ic@example.com', '/images/hotels/intercontinental.jpg', 'Mid-century modern landmark on Minto Road, next to Ramna Park. Elegant rooms, a rooftop bar with city views and an award-winning spa.', '2024-02-09 10:00:00'),
  (9, 'radissonctg', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Radisson Blu Chattogram Bay View', 813, 'SS Khaled Road, Lalkhan Bazar, Chattogram 4000', '01811667788', 'bayview@example.com', '/images/hotels/radisson-chattogram.jpg', 'Perched on a hill over the port city, every room looks out across Chattogram towards the Karnaphuli and the Bay of Bengal.', '2024-02-09 10:00:00'),
  (10, 'grandsultan', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Grand Sultan Tea Resort & Golf', 2595, 'Radhanagar, Sreemangal, Moulvibazar 3210', '01911445566', 'reservation.grandsultan@example.com', '/images/hotels/grand-sultan.jpg', 'A five-star retreat surrounded by tea gardens, with a nine-hole golf course, three pools and the Oronno Bilash restaurant.', '2024-02-09 10:00:00'),
  (11, 'runmoy', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Runmoy Resort Sajek', 351, 'Ruilui Para, Sajek Valley, Rangamati', '01811990011', 'runmoy.sajek@example.com', '/images/hotels/runmoy-sajek.jpg', 'Bright cottages on the ridge of Sajek with a front-row seat to the sea of clouds every morning.', '2024-02-09 10:00:00'),
  (12, 'nilgiriresort', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Nilgiri Hill Resort', 949, 'Nilgiri, Thanchi Road, Bandarban', '01769000111', 'nilgiri.resort@example.com', '/images/hotels/nilgiri-resort.jpg', 'Run by the Bangladesh Army at 2,200 feet, the cottages at Nilgiri sit right in the clouds during the monsoon. Book well in advance.', '2024-02-09 10:00:00');
