INSERT INTO restaurant (username, password, name, cuisine, union_id, plot_no, road_no, road_name, zip_code, phone_no, email, image, price_point, description) VALUES
  ('hajibiryani', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Haji Biryani', 'Biryani', 3306, '70', '1', 'Kazi Alauddin Road, Nazira Bazar', '1100', '01711100100', 'hajibiryani@example.com', '/images/food/haji-biryani.jpg', '$', 'Serving mutton biryani wrapped in shal leaves from the same Old Dhaka corner since 1939.'),
  ('starkabab', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Star Kabab & Restaurant', 'Bangladeshi', 3271, '61', '4', 'Dhanmondi', '1205', '01711100200', 'starkabab@example.com', '/images/food/bhuna-khichuri.jpg', '$', 'A Dhaka institution for bhuna khichuri, kala bhuna and kebabs at any hour of the day.'),
  ('nannabiryani', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Nanna Biryani', 'Biryani', 3310, '2', '1', 'Becharam Dewri', '1100', '01711100300', 'nannabiryani@example.com', '/images/food/morog-polao.jpg', '$', 'Old Dhaka''s legendary morog polao, slow-cooked chicken pulao with a hint of rose water.'),
  ('sultansdine', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Sultan''s Dine', 'Kacchi', 3271, '14', '27', 'Dhanmondi', '1209', '01711100400', 'sultansdine@example.com', '/images/food/kacchi.jpg', '$$', 'Basmati kacchi biryani with tender mutton and potatoes, served with borhani.'),
  ('fakruddin', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Fakruddin Biryani', 'Biryani', 3271, '1', '10', 'Baily Road', '1000', '01711100500', 'fakruddin@example.com', '/images/food/tehari.jpg', '$$', 'Famous for their beef tehari and kacchi, cooked by the family recipe since the 1960s.'),
  ('alrazzak', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Al-Razzak Restaurant', 'Kebab & Mughlai', 3306, '29', '2', 'North South Road, Bangshal', '1100', '01711100600', 'alrazzak@example.com', '/images/food/kebab.jpg', '$', 'Suti kebab, chaap and naan straight from the charcoal grill in the heart of Old Dhaka.'),
  ('bakarkhaniwala', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Puran Dhaka Bakarkhani', 'Bakery & Snacks', 3310, '5', '3', 'Lalbagh Road', '1211', '01711100700', 'bakarkhaniwala@example.com', '/images/food/bakarkhani.jpg', '$', 'Crisp, layered bakarkhani baked fresh in a clay tandoor every morning near Lalbagh Fort.'),
  ('fuchkacorner', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Dhanmondi Fuchka Corner', 'Street Food', 3271, '8', '8', 'Dhanmondi Lake', '1205', '01711100800', 'fuchkacorner@example.com', '/images/food/chotpoti.jpg', '$', 'Tangy fuchka and chotpoti by the lake, the evening ritual of every Dhaka student.'),
  ('mezbanbari', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Mezban Bari', 'Mezbani', 813, '36', '2', 'GEC Circle', '4000', '01811100900', 'mezbanbari@example.com', '/images/food/mezbani.jpg', '$$', 'Authentic Chattogram mezbani beef and kala bhuna, just like the feasts back home.'),
  ('panshi', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Panshi Restaurant', 'Bangladeshi', 2513, '12', '1', 'Zindabazar', '3100', '01911101000', 'panshi@example.com', '/images/food/bangladeshi-thali.jpg', '$', 'Endless bhorta, rice and curries at Sylhet''s busiest family restaurant.'),
  ('oronnobilash', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Oronno Bilash', 'Fine Dining', 2595, '1', '1', 'Grand Sultan Resort, Radhanagar', '3210', '01911101100', 'oronnobilash@example.com', '/images/food/oronno-bilash.jpg', '$$$', 'Fine dining among the tea gardens of Sreemangal with a Bangladeshi and continental menu.'),
  ('mermaidcafe', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Mermaid Beach Cafe', 'Seafood', 848, '1', '1', 'Marine Drive, Rezu Khal', '4750', '01811101200', 'mermaidcafe@example.com', '/images/food/doi-chingri.jpg', '$$$', 'Barefoot dining on the beach with grilled seafood, prawn curries and Bay of Bengal sunsets.'),
  ('ilishghor', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Kirtonkhola Ilish Ghor', 'Bangladeshi', 2243, '22', '4', 'Launch Ghat Road', '8200', '01711101300', 'ilishghor@example.com', '/images/food/shorshe-ilish.jpg', '$$', 'Shorshe ilish fresh off the boats at Barisal launch ghat.'),
  ('boishakhi', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Boishakhi Panta House', 'Bangladeshi', 1241, '3', '1', 'Shaheb Bazar', '6100', '01511101400', 'boishakhi@example.com', '/images/food/panta-ilish.jpg', '$', 'Panta bhat, fried ilish and bhorta platters, Pohela Boishakh every day of the year.'),
  ('pithaghor', '$2b$10$TXzODSB5f5B6EejM8fwvxOH6cl0Ou1N9RT1XtbFKV8d1nYC7MJ0zu', 'Rangpur Pitha Ghor', 'Desserts', 4034, '6', '2', 'Station Road', '5400', '01811101500', 'pithaghor@example.com', '/images/food/pitha.jpg', '$', 'Winter pitha all year round: chitoi, bhapa and patishapta with date molasses.');
INSERT INTO tourist_spot (spot_id, union_id, name, blog_description, image) VALUES
  (1, 824, 'Cox''s Bazar Sea Beach', 'The longest natural sea beach in the world, stretching over 120 km of golden sand along the Bay of Bengal. Come for the sunsets, stay for the fresh seafood and the marine drive to Teknaf.', '/images/spots/coxs-bazar.jpg'),
  (2, 882, 'Saint Martin''s Island', 'Bangladesh''s only coral island, a short ferry ride from Teknaf. Coconut palms, turquoise water and rocky coral beaches make it the country''s favourite winter escape.', '/images/spots/saint-martin.jpg'),
  (3, 351, 'Sajek Valley', 'Nestled in the Chittagong Hill Tracts, Sajek Valley floats above a sea of clouds at dawn. Indigenous villages, bamboo cottages and endless green hills all around.', '/images/spots/sajek.jpg'),
  (4, 949, 'Nilgiri', 'One of the highest tourist points in Bandarban, where you can literally touch the clouds during the monsoon. The road up is an adventure of its own.', '/images/spots/nilgiri.jpg'),
  (5, 947, 'Nafakhum Waterfall', 'Often called the Niagara of Bangladesh, Nafakhum is reached by boat and on foot through Remakri along the Sangu river. Remote, wild and worth every step.', '/images/spots/nafakhum.jpg'),
  (6, 343, 'Kaptai Lake', 'The largest man-made lake in the country, with emerald water winding between the hills of Rangamati. Take a boat to Shuvolong falls or cross the famous hanging bridge.', '/images/spots/kaptai-lake.jpg'),
  (7, 2599, 'Tea Gardens of Srimangal', 'The Tea Capital of Bangladesh, known for its expansive tea estates, scenic landscapes and diverse wildlife. Do not leave without trying the seven-layer tea.', '/images/spots/srimangal-tea.jpg'),
  (8, 2489, 'Ratargul Swamp Forest', 'Bangladesh''s only freshwater swamp forest, offering serene boat rides amidst lush, half-submerged trees. Best visited in the monsoon when the water is high.', '/images/spots/ratargul.jpg'),
  (9, 2491, 'Jaflong', 'Where the Piyain river spills out of the Meghalaya hills onto beds of stone. Crystal-clear water, tea gardens and the hanging bridge of Dauki in the distance.', '/images/spots/jaflong.jpg'),
  (10, 2490, 'Bichanakandi', 'A picturesque spot in Sylhet known for its crystal-clear river, rolling hills and stunning landscapes. Wade through the cool water over a bed of polished stones.', '/images/spots/bichanakandi.jpg'),
  (11, 2556, 'Lawachara National Park', 'A tropical rainforest famous for its hoolock gibbons and the railway line that cuts straight through the jungle. Guided trails start right from the gate.', '/images/spots/lawachara.jpg'),
  (12, 2737, 'Tanguar Haor', 'A vast wetland near the Meghalaya border that turns into an inland sea in the monsoon. Spend a night on a houseboat and wake up to migratory birds.', '/images/spots/tanguar-haor.jpg'),
  (13, 3310, 'Lalbagh Fort', 'A 17th-century Mughal fort in Old Dhaka, known for its architectural grandeur and the tomb of Pari Bibi. A calm green garden in the middle of the busiest part of the city.', '/images/spots/lalbagh-fort.jpg'),
  (14, 3306, 'Ahsan Manzil', 'The Pink Palace on the bank of the Buriganga, once home of the Nawabs of Dhaka. Now a museum showing the grandeur of the Nawab era.', '/images/spots/ahsan-manzil.jpg'),
  (15, 2980, 'Panam Nagar', 'A ghost city of colonial merchant houses in Sonargaon, the ancient capital of Bengal. Walk down a single street lined with crumbling 19th-century mansions.', '/images/spots/panam-nagar.jpg'),
  (16, 2979, 'Sonargaon Folk Arts and Crafts Museum', 'Showcasing traditional Bangladeshi arts and crafts in the Bara Sardar Bari palace. The lake and gardens around it make a perfect day trip from Dhaka.', '/images/spots/sonargaon-museum.jpg'),
  (17, 3271, 'Jatiyo Smriti Soudho', 'The National Martyrs'' Memorial at Savar, built in honour of those who gave their lives in the Liberation War of 1971. Seven triangular planes rise from a sea of green.', '/images/spots/smriti-soudho.jpg'),
  (18, 1929, 'Sundarbans Mangrove Forest', 'The largest mangrove forest in the world, home to the elusive Bengal tiger and unique aquatic biodiversity. Trips leave from Mongla and Khulna by launch.', '/images/spots/sundarbans.jpg'),
  (19, 1959, 'Sixty Dome Mosque', 'A UNESCO World Heritage mosque built by Khan Jahan Ali in the 15th century. Despite the name it has 77 domes, and the terracotta work is stunning.', '/images/spots/sixty-dome.jpg'),
  (20, 1426, 'Paharpur Buddhist Vihara', 'Somapura Mahavihara, once the largest Buddhist monastery south of the Himalayas. A UNESCO World Heritage site with over a thousand years of history.', '/images/spots/paharpur.jpg'),
  (21, 1213, 'Mahasthangarh', 'The earliest urban archaeological site found in Bangladesh, dating back to the 3rd century BC. Walk the old brick walls of ancient Pundranagara.', '/images/spots/mahasthangarh.jpg'),
  (22, 1241, 'Puthia Temple Complex', 'The largest cluster of historic Hindu temples in Bangladesh, built by the Puthia Raj family around a peaceful lake.', '/images/spots/puthia.jpg'),
  (23, 3744, 'Kantajew Temple', 'An 18th-century temple in Dinajpur famous for its terracotta panels that tell stories from the Mahabharata and Ramayana on every surface.', '/images/spots/kantajew.jpg'),
  (24, 4034, 'Tajhat Palace', 'A grand white palace built by a jeweller-turned-zamindar in Rangpur, now home to the Rangpur Museum. The staircase alone is worth the trip.', '/images/spots/tajhat.jpg'),
  (25, 2163, 'Kuakata Sea Beach', 'Famous for witnessing both sunrise and sunset over the Bay of Bengal, earning it the nickname Daughter of the Sea.', '/images/spots/kuakata.jpg'),
  (26, 2272, 'Durga Sagar', 'One of the largest ponds in the south, dug in 1780 and surrounded by quiet woods. Winter brings flocks of migratory birds to the island in the middle.', '/images/spots/durga-sagar.jpg'),
  (27, 4462, 'Birishiri', 'Blue-green lakes of white china clay hills near the Someshwari river. A peaceful corner of Netrokona with Garo and Hajong heritage.', '/images/spots/birishiri.jpg'),
  (28, 4287, 'Shashi Lodge', 'The Rajbari of Mymensingh, a 19th-century zamindar palace with a marble fountain garden, right by the Brahmaputra.', '/images/spots/shashi-lodge.jpg');
